/**
 * Replicated data model shared by every strategy, the app, the server and the simulator.
 * See "Shared design" in the implementation plan; field names here are used verbatim in the paper.
 */

/** 'server', 'c1', 'c2', ... or a device UUID. */
export type ReplicaId = string;

/** UUID v4, generated by the replica that creates the record. */
export type RecordId = string;

export interface Payment {
  /** UUID of the payment, generated by the replica that records it. */
  id: string;
  /** YYYY-MM-DD */
  date: string;
  amountCents: number;
}

export type BillingCycle = 'WEEKLY' | 'MONTHLY' | 'YEARLY';

export const BILLING_CYCLES: readonly BillingCycle[] = ['WEEKLY', 'MONTHLY', 'YEARLY'];

export interface SubscriptionDoc {
  id: RecordId;
  name: string;
  /** Integer; the app converts to and from its decimal `amount`. */
  amountCents: number;
  currency: string;
  billingCycle: BillingCycle;
  /** YYYY-MM-DD */
  nextPaymentDate: string;
  category: string;
  isActive: boolean;
  notes: string;
  /** Set semantics, always returned sorted. */
  tags: string[];
  /** Append-only, always returned sorted by (date, id). */
  payments: Payment[];
  /** Counter: how many other people share the subscription. */
  sharedWith: number;
}

/** The scalar part of a record: every field that is set by `setField`. */
export type ScalarFields = Omit<SubscriptionDoc, 'id' | 'tags' | 'payments' | 'sharedWith'>;

export type ScalarFieldName = keyof ScalarFields;

export type ScalarValue = ScalarFields[ScalarFieldName];

export const SCALAR_FIELDS: readonly ScalarFieldName[] = [
  'name',
  'amountCents',
  'currency',
  'billingCycle',
  'nextPaymentDate',
  'category',
  'isActive',
  'notes',
];

/** Field classes used by the hybrid strategy and by the per-type analysis (RQ3). */
export type FieldClass = 'SIMPLE' | 'CRITICAL' | 'SET' | 'APPEND' | 'COUNTER';

export type FieldName = Exclude<keyof SubscriptionDoc, 'id'>;

export const FIELD_CLASS: Readonly<Record<FieldName, FieldClass>> = {
  name: 'SIMPLE',
  currency: 'SIMPLE',
  billingCycle: 'SIMPLE',
  category: 'SIMPLE',
  isActive: 'SIMPLE',
  notes: 'SIMPLE',
  amountCents: 'CRITICAL',
  nextPaymentDate: 'CRITICAL',
  tags: 'SET',
  payments: 'APPEND',
  sharedWith: 'COUNTER',
};

export function isScalarFieldName(name: unknown): name is ScalarFieldName {
  return typeof name === 'string' && (SCALAR_FIELDS as readonly string[]).includes(name);
}

/** A new record as created by a `create` op: no tags, no payments, shared with nobody. */
export function emptyDoc(id: RecordId, fields: ScalarFields): SubscriptionDoc {
  return {
    id,
    name: fields.name,
    amountCents: fields.amountCents,
    currency: fields.currency,
    billingCycle: fields.billingCycle,
    nextPaymentDate: fields.nextPaymentDate,
    category: fields.category,
    isActive: fields.isActive,
    notes: fields.notes,
    tags: [],
    payments: [],
    sharedWith: 0,
  };
}

/** Orders payments by (date, id), the canonical order every strategy returns them in. */
export function comparePayments(a: Payment, b: Payment): number {
  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
  if (a.id !== b.id) return a.id < b.id ? -1 : 1;
  return 0;
}

/**
 * Returns a copy of `doc` in canonical form: tags deduplicated and sorted, payments sorted by (date, id).
 * Strategies call this in `read()` so that equal states are deep-equal.
 */
export function normalizeDoc(doc: SubscriptionDoc): SubscriptionDoc {
  return {
    ...doc,
    tags: [...new Set(doc.tags)].sort(),
    payments: [...doc.payments].map((p) => ({ ...p })).sort(comparePayments),
  };
}
